{
  "name": "abide",
  "version": "0.0.0",
  "private": true,
  "description": "Enforce your own AGENTS.md rules on every edit a coding agent makes, from outside its context window.",
  "license": "MIT",
  "author": "Coldtea AI",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/coldteadotai/abide.git"
  },
  "type": "module",
  "packageManager": "pnpm@10.5.2",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "pnpm -r run build",
    "typecheck": "pnpm -r run typecheck",
    "test": "pnpm -r run test",
    "verify": "pnpm run format:check && pnpm run build && pnpm run typecheck && pnpm run test",
    "format": "prettier --write .",
    "format:check": "prettier --check ."
  },
  "devDependencies": {
    "prettier": "3",
    "typescript": "7.0.2",
    "vitest": "4.1.11"
  }
}

{
  "name": "@coldtea/abide-schema",
  "version": "0.0.5",
  "description": "The Abide contract: the rubric document a coding agent compiles from a repository's instruction files, and the verdict a check returns.",
  "license": "MIT",
  "author": "Coldtea AI",
  "type": "module",
  "sideEffects": false,
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "src",
    "json-schema",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "node ../../scripts/rm.mjs dist && tsc -p tsconfig.build.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run"
  },
  "dependencies": {
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@types/node": "^22",
    "typescript": "7.0.2",
    "vitest": "4.1.11"
  }
}
